	&lt;TD colspan=2 class="tr1 td95"&gt;&lt;P class="p406 ft8"&gt;Ditt liv i sin helhet&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td96"&gt;&lt;P class="p409 ft8"&gt;66&lt;/P&gt;&lt;/TD&gt;
