	&lt;TD class="tr14 td6"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr14 td154"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr14 td149"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
