&lt;TR&gt;
	&lt;TD class="tr12 td150"&gt;&lt;P class="p47 ft8"&gt;&lt;NOBR&gt;20–29&lt;/NOBR&gt; år&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr12 td151"&gt;&lt;P class="p579 ft122"&gt;41&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td149"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr12 td6"&gt;&lt;P class="p47 ft8"&gt;&lt;NOBR&gt;30–44&lt;/NOBR&gt; år&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr12 td154"&gt;&lt;P class="p579 ft122"&gt;30&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr12 td149"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr14 td83"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr14 td148"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
