	&lt;TD class="tr10 td311"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr10 td23"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr10 td113"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr10 td114"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr1 td272"&gt;&lt;P class="p577 ft8"&gt;behandling&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td273"&gt;&lt;P class="p30 ft8"&gt;82&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td274"&gt;&lt;P class="p821 ft8"&gt;80&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td312"&gt;&lt;P class="p406 ft8"&gt;78&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td276"&gt;&lt;P class="p431 ft8"&gt;6&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td277"&gt;&lt;P class="p821 ft8"&gt;5&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td313"&gt;&lt;P class="p818 ft8"&gt;2&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td278"&gt;&lt;P class="p831 ft8"&gt;8&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr1 td279"&gt;&lt;P class="p831 ft8"&gt;10&lt;/P&gt;&lt;/TD&gt;
