&lt;P class="p41 ft27"&gt;SOU 2017:92 Den könsbekräftande vården&lt;/P&gt;
&lt;TABLE cellpadding=0 cellspacing=0 style="width: 424px;margin-top: 29px;font: 12px 'Arial';"&gt;
&lt;TR&gt;
	&lt;TD class="tr1 td6"&gt;&lt;P class="p577 ft110"&gt;Tabell 15.11&lt;/P&gt;&lt;/TD&gt;
	&lt;TD colspan=2 style="padding: 0px;margin: 0px;width: 348px;vertical-align: bottom;" class="tr1"&gt;&lt;P class="p3 ft110"&gt;Kötid för att få träffa endokrinolog efter diagnos&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr15 td83"&gt;&lt;P class="p3 ft168"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 82px;vertical-align: bottom;" class="tr15"&gt;&lt;P class="p3 ft168"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 266px;vertical-align: bottom;" class="tr15"&gt;&lt;P class="p3 ft168"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr12 td97"&gt;&lt;P class="p577 ft8"&gt;Team&lt;/P&gt;&lt;/TD&gt;
