	&lt;TD style="border-bottom: #e5e5e5 1px solid;padding: 0px;margin: 0px;width: 266px;vertical-align: bottom;background: #e5e5e5;" class="tr12"&gt;&lt;P class="p430 ft8"&gt;Tid&lt;/P&gt;&lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
