	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 219px;vertical-align: bottom;" class="tr14"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 64px;vertical-align: bottom;" class="tr14"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 70px;vertical-align: bottom;" class="tr14"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="border-bottom: #000000 1px solid;padding: 0px;margin: 0px;width: 71px;vertical-align: bottom;" class="tr14"&gt;&lt;P class="p3 ft115"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
