	&lt;TD class="tr10 td79"&gt;&lt;P class="p577 ft114"&gt;Källa: TGEU 2017b&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr10 td209"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="padding: 0px;margin: 0px;width: 87px;vertical-align: bottom;" class="tr10"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
