	&lt;TD class="tr10 td317"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD style="padding: 0px;margin: 0px;width: 86px;vertical-align: bottom;" class="tr10"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
	&lt;TD class="tr10 td209"&gt;&lt;P class="p3 ft21"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
