	&lt;TD style="border-top: #000000 1px solid;padding: 0px;margin: 0px;width: 26px;vertical-align: bottom;" class="tr10"&gt;&lt;P class="p3 ft4"&gt;&amp;nbsp;&lt;/P&gt;&lt;/TD&gt;
