 <sourceid></sourceid>
 <dokument_url_text>https://data.riksdagen.se/dokument/HC12682/text</dokument_url_text>
 <dokument_url_html>https://data.riksdagen.se/dokument/HC12682</dokument_url_html>
 <dokumentstatus_url_xml>https://data.riksdagen.se/dokumentstatus/HC12682</dokumentstatus_url_xml>
 <html>&lt;h2&gt;Svar på fråga 2024/25:682 Jaktmöjligheter i naturreservat&lt;/h2&gt;
&lt;p class="Till"&gt;till Statsrådet Romina Pourmokhtari (L)&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

		&lt;div class="Section1"&gt;
			&lt;p class="Title"&gt;
				&lt;a name="Start"&gt;&lt;/a&gt;&lt;span&gt;Svar på fråga 2024/25:682 av Marie Olsson (S)&lt;/span&gt;&lt;br&gt;&lt;span&gt;Jaktmöjligheter i Korpimäki naturreservat&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span style="-aw-import:ignore"&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Marie Olsson (S) har frågat mig när jägarna i Orsa och i resten av Dalarna kan få ett beslut från regeringen gällande jaktmöjligheterna i Korpimäki naturreservat.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Frågan ställs med anledning av att Länsstyrelsen i Dalarnas län har fattat beslut om att utöka möjligheterna till jakt inom Korpimäki naturreservat. Detta beslut har överklagats till regeringen.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Utgångspunkten i regeringens hantering av överklagade beslut enligt miljöbalken är att handläggningen ska ske skyndsamt, effektivt och utan att rättssäkerheten eftersätts.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Jag kan i dagsläget inte säga när regeringen kommer att fatta beslut i ärendet och då detta är ett pågående förvaltningsärende bör jag inte föregripa ett beslut i ärendet genom uttalanden i frågan.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span style="-aw-import:ignore"&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Stockholm den &lt;/span&gt;&lt;span style="-aw-sdt-tag:''"&gt;&lt;span&gt;22 januari 2025&lt;/span&gt;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="Brdtextutanavstnd"&gt;
				&lt;span style="-aw-import:ignore"&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="Brdtextutanavstnd"&gt;
				&lt;span style="width:269.35pt; display:inline-block; -aw-tabstop-align:left; -aw-tabstop-pos:269.35pt"&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="Brdtextutanavstnd"&gt;
				&lt;span style="-aw-import:ignore"&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p class="BodyText"&gt;
				&lt;span&gt;Romina Pourmokhtari&lt;/span&gt;
			&lt;/p&gt;
		&lt;/div&gt;
	</html>
</dokument>
