--&gt;&lt;/style&gt;&lt;div class="pconf"&gt;&lt;span class="sidhuvud_publikation"&gt;Motion till riksdagen&lt;/span&gt;&lt;br/&gt;
&lt;span class="sidhuvud_beteckning"&gt;2019/20:1415&lt;/span&gt;&lt;br/&gt;
&lt;span class="MotionarLista"&gt;av Olle Thorell m.fl. (S)&lt;/span&gt;&lt;br/&gt;
&lt;h1&gt;Konsekvenser av Arbetsförmedlingens omorganisation&lt;/h1&gt;
&lt;hr class="sidhuvud_linje"/&gt;


		&lt;div class="Section1"&gt;
			&lt;h1 style="margin-bottom:15pt; -aw-sdt-tag:CC_Boilerplate_4; -aw-sdt-title:CC_Boilerplate_4"&gt;
				&lt;span&gt;Förslag till riksdagsbeslut&lt;/span&gt;
			&lt;/h1&gt;
			&lt;p class="Frslagstext" style="-aw-sdt-tag:0cd569f3-3f69-4bad-9f95-532f4159ff45; -aw-sdt-title:'Yrkande 1'"&gt;
				&lt;span&gt;Riksdagen ställer sig bakom det som anförs i motionen om konsekvenser av Arbetsförmedlingens omorganisation och tillkännager detta för regeringen.&lt;/span&gt;
			&lt;/p&gt;
			&lt;h1 style="-aw-sdt-tag:CC_Motivering_Rubrik; -aw-sdt-title:CC_Motivering_Rubrik"&gt;
				&lt;a name="MotionsStart"&gt;&lt;/a&gt;&lt;span&gt;Motivering&lt;/span&gt;
			&lt;/h1&gt;
			&lt;p class="Normalutanindragellerluft"&gt;
				&lt;span&gt;Arbetsförmedlingen har under 2019 beslutat om en stor reducering av sin organisation och avveckling utav stora delar av kontorsnätet. Det väntas medföra direkta, betydande och negativa konsekvenser för det lokala samarbetet och samverkan mellan myndig&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;heten och många av landets kommuner, likväl som för den regionala tillväxten och utvecklingen på sikt.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Problemen som den hastiga omläggningen av Arbetsförmedlingens organisation har inneburit har drabbat mängder av kommuner&lt;/span&gt;&lt;span&gt;.&lt;/span&gt;&lt;span&gt; &lt;/span&gt;&lt;span&gt;H&lt;/span&gt;&lt;span&gt;är visar vi på exempel från Fagersta i vår valkrets Västmanland, men det som beskrivs gäller för ett stort antal av landets mindre och mellanstora kommuner.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Det har funnits en väl utvecklad och väl fungerande samverkan mellan Arbetsför&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;medlingen och Fagersta kommun i en rad olika former. På ledningsnivå träffas repre&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;sentanter för Arbetsförmedlingen och Fagersta kommun regelbundet i syfte att hålla en uppdaterad lägesbild.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Inom socialförvaltningen i Fagersta kommun så har det bedrivits insatser i samar&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;bete med Arbetsförmedlingen, i storleksordningen har Arbetsförmedlingen finansierat dessa med nära 16 miljoner kronor direkt kopplat till åtgärder för arbetslösa. Detta in&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;kluderar inte extratjänster och andra bidragsanställningar inom äldreomsorg och skola. En minskad statlig finansiering av dessa åtgärder kommer få som följd att fler personer kommer behöva uppbära ekonomiskt bistånd. I praktiken skulle staten lassa över kost&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;nader på kommunen.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Fagersta kommun arbetar för att minska individers behov av ekonomiskt bistånd. Färre insatser leder till ökat ekonomiskt bistånd samt längre tid med ekonomiskt bi&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;stånd.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Fagersta tillhör de bästa 25&lt;/span&gt;&lt;span&gt;&amp;#xa0;&lt;/span&gt;&lt;span&gt;% av kommunerna när det gäller långvarigt och/eller ut&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;betalt bistånd.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Varje vecka sker en genomgång tillsammans med och på plats hos Arbetsför&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;medlingen, där alla deltagare inom dessa verksamheter gås igenom och beslut fattas om insatser, förlängningar, avslutningar och andra nödvändiga förändringar. Det känns väl&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;digt avlägset att det kommer att fungera lika bra när det inte längre finns några handläg&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;gare.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;I dagsläget finns 1&lt;/span&gt;&lt;span&gt;&amp;#xa0;&lt;/span&gt;&lt;span&gt;700 inskrivna vid Arbetsförmedlingens kontor i Fagersta, om&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;kring hälften av dem är nyanlända och har en lång väg till arbetsmarknaden och egen försörjning. Vi har svårt att se att ambulerande handläggare från exempelvis Västerås kommer att kunna tillhandahålla det stöd och den service som krävs. En handläggare kan möjligen hinna med 3&lt;/span&gt;&lt;span&gt;–&lt;/span&gt;&lt;span&gt;4 klienter per dag och tillfälle, förutsatt att restiden medger detta. En omöjlig ekvation att alla hinns med.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Fagersta kommun har också sedan länge ett omfattande samarbete med Arbetsför&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;medlingen vad gäller arbetssökande med intresse för att starta företag, där kommunens näringslivsenhet har en rådgivande och hjälpande verksamhet för individer&lt;/span&gt;&lt;span&gt;,&lt;/span&gt;&lt;span&gt; &lt;/span&gt;&lt;span&gt;b&lt;/span&gt;&lt;span&gt;land annat med rådgivning kring affärsidén, marknadens behov och framtagande av affärsplaner. Kontorsnätets anpassning och osäkerheten kring arbetsförmedlingens framtida organi&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;sation har på detta en negativ påverkan.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;För Fagerstas del, där vi har en tydligt tudelad arbetsmarknad med en stor grupp ny&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;anlända och utlandsfödda som står långt från arbetsmarknaden samtidigt som de stora industriföretag som är motorn i den lokala ekonomin hämmas av bristen på adekvat kompetens, är frågetecknen kring kompetensförsörjning och arbetslöshet av avgörande betydelse för den framtida utvecklingen.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Det krävs effektiva lösningar för att säkerställa kompetensförsörjningen i såväl före&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;tag som offentlig sektor och här är matchning och utbildning helt avgörande. Det är i dagsläget osäkert i vilken omfattning och i vilken roll Arbetsförmedlingen kommer att vara delaktig i detta utvecklingsarbete&lt;/span&gt;&lt;span&gt;,&lt;/span&gt;&lt;span&gt; och denna osäkerhet påverkar det lokala och reg&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;ionala arbetet negativt.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Framför allt finns en betydande osäkerhet och negativ påverkan på de individer som omfattas av åtgärder och som riskerar att drabbas av Arbetsförmedlingens minskade närvaro ute i landet&lt;/span&gt;&lt;span&gt;, de s&lt;/span&gt;&lt;span&gt;om inte kan ta sig till ett kontor på annan ort, som inte kan till&lt;/span&gt;&lt;span&gt;&amp;#xad;&lt;/span&gt;&lt;span&gt;godogöra sig möjligheter till självbetjäning och som inte hinns med att tas om hand av ambulerande handläggare.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p&gt;
				&lt;span&gt;Dessa människor kommer inte att försvinna från de orter där kontoren läggs ned och redan idag sker en överföring av arbetsförmedlingens tidigare roll till kommunerna, då arbetssökande söker sig till kommunkontor för handledning av kommunala tjänstemän. Närheten till handläggare och direktkontakt med arbetssökande är av väsentlig betydelse för att kunna ge nödvändig service och personligt stöd.&lt;/span&gt;
			&lt;/p&gt;
			&lt;p style="-aw-sdt-tag:CC_Underskrifter; -aw-sdt-title:CC_Underskrifter"&gt;
				&lt;span&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;p style="-aw-sdt-tag:CC_Underskrifter; -aw-sdt-title:CC_Underskrifter"&gt;
				&lt;span&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
			&lt;table cellspacing="0" cellpadding="0" style="border-collapse:collapse; margin-left:0pt; width:100%"&gt;
				&lt;tr&gt;
					&lt;td style="padding-left:5.4pt; padding-right:5.4pt; vertical-align:bottom; width:1%"&gt;
						&lt;p class="Underskrifter" style="margin-top:15pt; margin-bottom:3pt; t-i:0pt; page-break-inside:avoid; line-height:15pt"&gt;
							&lt;span style="font-style:italic"&gt;Olle Thorell (S)&lt;/span&gt;
						&lt;/p&gt;
					&lt;/td&gt;
					&lt;td style="padding-left:5.4pt; padding-right:5.4pt; vertical-align:bottom; width:1%"&gt;
						&lt;p class="Underskrifter" style="margin-top:15pt; margin-bottom:3pt; t-i:0pt; page-break-inside:avoid; line-height:15pt"&gt;
							&lt;span style="font-style:italic"&gt;&amp;#xa0;&lt;/span&gt;
						&lt;/p&gt;
					&lt;/td&gt;
				&lt;/tr&gt;
				&lt;tr&gt;
					&lt;td style="padding-left:5.4pt; padding-right:5.4pt; vertical-align:bottom; width:1%"&gt;
						&lt;p class="Underskrifter" style="margin-top:15pt; margin-bottom:0pt; t-i:0pt; page-break-inside:avoid; line-height:15pt"&gt;
							&lt;span style="font-style:italic"&gt;Pia Nilsson (S)&lt;/span&gt;
						&lt;/p&gt;
					&lt;/td&gt;
					&lt;td style="padding-left:5.4pt; padding-right:5.4pt; vertical-align:bottom; width:1%"&gt;
						&lt;p class="Underskrifter" style="margin-top:15pt; margin-bottom:0pt; t-i:0pt; page-break-inside:avoid; line-height:15pt"&gt;
							&lt;span style="font-style:italic"&gt;Åsa Eriksson (S)&lt;/span&gt;
						&lt;/p&gt;
					&lt;/td&gt;
				&lt;/tr&gt;
			&lt;/table&gt;
			&lt;p style="line-height:4pt"&gt;
				&lt;span&gt;&amp;#xa0;&lt;/span&gt;
			&lt;/p&gt;
