 &lt;/style&gt;&lt;div class="body"&gt;&lt;table class="webbtabell"&gt;&lt;tr&gt;&lt;td valign="top" width="457"&gt;&lt;p&gt;RIKSDAGEN&lt;/p&gt;

			&lt;p&gt;MILJÖ- OCH JORDBRUKSUTSKOTTET&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;/table&gt;

    &lt;table class="webbtabell"&gt;&lt;tr&gt;&lt;td valign="top" width="99"&gt;&lt;p&gt;&lt;span class="bold "&gt;PROTOKOLL &lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="323"&gt;&lt;p&gt;&lt;span class="bold "&gt;UTSKOTTSSAMMANTRÄDE 201&lt;/span&gt;&lt;span class="bold "&gt;5&lt;/span&gt;&lt;span class="bold "&gt;/1&lt;/span&gt;&lt;span class="bold "&gt;6&lt;/span&gt;&lt;span class="bold "&gt;:&lt;/span&gt;&lt;span class="bold "&gt;31&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="99"&gt;&lt;p&gt;DATUM&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="323"&gt;&lt;p&gt;2016-04-19&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="99"&gt;&lt;p&gt;TID&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="323"&gt;&lt;p&gt;11.00 – 11.15 &lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="99"&gt;&lt;p&gt;NÄRVARANDE&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="323"&gt;&lt;p&gt;Se bilaga 1&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;/table&gt;

    &lt;table class="webbtabell"&gt;&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ 1&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Verksamheten i Europeiska unionen under 2015&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Utskottet behandlade frågan om yttrande till utrikesutskottet med anledning av skrivelse 2015/16:115 och en motion. &lt;/p&gt;

			&lt;p&gt;Utskottet beslutade att avge yttrande till utrikesutskottet.  &lt;/p&gt;

			&lt;p&gt;Ärendet bordlades.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ &lt;/span&gt;&lt;span class="bold "&gt;2&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Förslag till Europaparlamentets och rådets förordning om fastställande av bestämmelser om tillhandahållande på marknaden av CE-märkta göd&lt;/span&gt;&lt;span class="bold "&gt;selprodukter och om ändring av &lt;/span&gt;&lt;span class="bold "&gt;förordning (EG) nr 1069/2009 och (EG) nr 1107/2009&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Utskottet fortsatte subsidiaritetsprövning av KOM (2016) 157.&lt;/p&gt;

			&lt;p&gt;&lt;br /&gt;Utskottet ansåg att förslaget inte strider mot subsidiaritetsprincipen.&lt;br /&gt;&lt;br /&gt;Denna paragraf förklarades omedelbart justerad.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ 3&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Förslag till Europaparlamentets och rådets förordning om fastställande av den justeringsgrad&lt;/span&gt;&lt;span class="bold "&gt; &lt;/span&gt;&lt;span class="bold "&gt;som avses i förordning (EU) nr 1306/2013 för direktstöd avseende kalenderåret 2016&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Utskottet fortsatte subsidiaritetsprövning av KOM (2016) 159.&lt;/p&gt;

			&lt;p&gt;&lt;br /&gt;Utskottet ansåg att förslaget inte strider mot subsidiaritetsprincipen.&lt;br /&gt;&lt;br /&gt;Denna paragraf förklarades omedelbart justerad.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ 4&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Inkomna skrivelser&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;En inkommen skrivelse anmäldes och lades till handlingarna.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ &lt;/span&gt;&lt;span class="bold "&gt;5&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Utländskt besök&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Utskottet beslutade att ta emot en delegation från den tyska förbundsdagen torsdagen den 26 maj 2016 kl. 10.15–11.00. Följande ledamöter anmälde sig:&lt;/p&gt;

			&lt;p&gt;Matilda Ernkrans (S), Kristina Yngwe (C), Jonas Jacobsson Gjörtler (M),&lt;/p&gt;

			&lt;p&gt;Isak From (S), Johan Hultberg (M), Maria Strömkvist (S), Martin Kinnunen&lt;/p&gt;

			&lt;p&gt;(SD), Åsa Coenraads (M), Stina Bergström (MP), Gunilla Nordgren (M),&lt;/p&gt;

			&lt;p&gt;Monica Haider (S), Lars Tysklind (L), Jens Holm (V), Lars-Axel Nordell&lt;/p&gt;

			&lt;p&gt;(KD), Marianne Pettersson (S), Johan Büser (S) och Emma Nohrén (MP).&lt;/p&gt;

			&lt;p&gt;Mötet äger rum i utskottets sessionssal RÖ7-26.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ &lt;/span&gt;&lt;span class="bold "&gt;6&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Veterandagen&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Till veterandagen onsdagen den 11 maj 2016 kl. 14.30–15.30 anmälde sig Matilda Ernkrans (S), Åsa Coenraads (M), Lars Tysklind (L) och Lars-Axel Nordell (KD).&lt;br /&gt;Mötet äger rum i utskottets sessionssal RÖ7-26.&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="28"&gt;&lt;p&gt;&lt;span class="bold "&gt;§ 7&lt;/span&gt;&lt;/p&gt;

			&lt;/td&gt;&lt;td valign="top" width="347" colspan="2"&gt;&lt;p&gt;&lt;span class="bold "&gt;Nästa sammanträde&lt;/span&gt;&lt;/p&gt;

			&lt;p&gt;Nästa sammanträde äger rum tisdagen den 26 april 2016 kl. 11.00. &lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

		&lt;tr&gt;&lt;td valign="top" width="358" colspan="2"&gt;&lt;p&gt;Vid protokollet&lt;/p&gt;

			&lt;p&gt;Justeras den 28 april 2016&lt;/p&gt;

			&lt;p&gt;Matilda Ernkrans&lt;/p&gt;

			&lt;/td&gt;&lt;/tr&gt;

