	&lt;TD class="tr5 td19"&gt;&lt;SPAN class="p3 ft4"&gt;intäktsminskningar eller kostnadsökningar. Ett annat synnerligt skäl kan&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD rowspan=2 class="tr36 td66"&gt;&lt;SPAN class="p13 ft4"&gt;16&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
