	&lt;TD class="tr4 td19"&gt;&lt;SPAN class="p3 ft4"&gt;genomsnitt var nettokostnaden 2 576 kronor per invånare 2003. Den&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td66"&gt;&lt;SPAN class="p3 ft8"&gt;&amp;nbsp;&lt;/SPAN&gt; &lt;/TD&gt;
