&lt;TR&gt;
	&lt;TD class="tr4 td19"&gt;&lt;SPAN class="p3 ft4"&gt;högsta kostnaden hade Bräcke kommun med 5 452 kronor per invånare&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td66"&gt;&lt;SPAN class="p3 ft8"&gt;&amp;nbsp;&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
