	&lt;TD class="tr7 td68"&gt;&lt;SPAN class="p13 ft70"&gt;2002&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr7 td68"&gt;&lt;SPAN class="p13 ft70"&gt;2003&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr7 td68"&gt;&lt;SPAN class="p13 ft70"&gt;2004&lt;/SPAN&gt; &lt;/TD&gt;
