	&lt;TD class="tr4 td19"&gt;&lt;SPAN class="p3 ft4"&gt;med 5 procent sedan 1999. Mätningen av antal personer med LSS-&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td66"&gt;&lt;SPAN class="p3 ft8"&gt;&amp;nbsp;&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr4 td19"&gt;&lt;SPAN class="p3 ft4"&gt;insatser och antal insatser sker vid en särskild mätdag. Kommunerna&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td66"&gt;&lt;SPAN class="p3 ft8"&gt;&amp;nbsp;&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
