	&lt;TD class="tr4 td425"&gt;&lt;SPAN class="p277 ft4"&gt;Minskade utsläpp av kväve till vatten, 497 ton/år&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td28"&gt;&lt;SPAN class="p3 ft8"&gt;&amp;nbsp;&lt;/SPAN&gt; &lt;/TD&gt;
