	&lt;TD class="tr4 td116"&gt;&lt;SPAN class="p13 ft25"&gt;Ökat stöd för bastandvård åt äldre&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td117"&gt;&lt;SPAN class="p269 ft25"&gt;225&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
&lt;TR&gt;
	&lt;TD class="tr5 td116"&gt;&lt;SPAN class="p13 ft25"&gt;Högkostnadsskydd för äldre för kronor,&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr5 td117"&gt;&lt;SPAN class="p269 ft25"&gt;150&lt;/SPAN&gt; &lt;/TD&gt;
&lt;/TR&gt;
