	&lt;TD class="tr4 td116"&gt;&lt;SPAN class="p13 ft25"&gt;Bettskena blir bastandvård&lt;/SPAN&gt; &lt;/TD&gt;
	&lt;TD class="tr4 td117"&gt;&lt;SPAN class="p269 ft25"&gt;25&lt;/SPAN&gt; &lt;/TD&gt;
