          &lt;td valign="top" colspan="2" style="border-bottom-width: 0.5pt; border-bottom-style: solid; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: top; width: 106.26mm;"&gt;
            &lt;p class="DokumentRubrik" style="word-break-inside: hyphenate;"&gt;&lt;a id="Huvudrubrik" name="Huvudrubrik"&gt;&lt;/a&gt;Riksrevisionens styrelses redog&amp;ouml;relse om Riksrevisionens &amp;aring;rsredovisning f&amp;ouml;r 2009 &lt;/p&gt;
          &lt;/td&gt;
          &lt;td valign="top" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: top; width: 25.01mm;"&gt;
          &lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
          &lt;td valign="top" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: top; width: 53.13mm;"&gt;
          &lt;/td&gt;
          &lt;td valign="top" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: top; width: 53.13mm;"&gt;
          &lt;/td&gt;
          &lt;td valign="top" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: top; width: 25.01mm;"&gt;
