      &lt;colgroup&gt;&lt;col width="161"/&gt;&lt;col width="65"/&gt;&lt;col width="65"/&gt;&lt;col width="65"/&gt;&lt;/colgroup&gt;
      &lt;tbody&gt;
        &lt;tr&gt;
