            &lt;p class="Normal" style="line-height: normal; margin-top: 0.0mm; text-align: right; word-break-inside: hyphenate; font-family: &amp;quot;Calibri&amp;quot;; font-size: 8.0pt;"&gt;16 144&lt;/p&gt;
          &lt;/td&gt;
          &lt;td valign="bottom" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: bottom; width: 17.22mm;"&gt;
            &lt;p class="Normal" style="line-height: normal; margin-top: 0.0mm; text-align: right; word-break-inside: hyphenate; font-family: &amp;quot;Calibri&amp;quot;; font-size: 8.0pt;"&gt;31 332&lt;/p&gt;
          &lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
          &lt;td valign="bottom" colspan="1" style="border-bottom-style: hidden; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: bottom; width: 42.55mm;"&gt;
