          &lt;td valign="bottom" colspan="1" style="border-bottom-width: 0.5pt; border-bottom-style: solid; border-bottom-color: #000000; border-left-style: hidden; border-left-color: #000000; border-right-style: hidden; border-right-color: #000000; border-top-style: hidden; border-top-color: #000000; padding-bottom: 0.0mm; padding-left: 1.23mm; padding-right: 1.23mm; padding-top: 0.0mm; vertical-align: bottom; width: 20.6mm;"&gt;
