    &lt;table class="webbtabell"&gt;&lt;tr&gt;&lt;td valign="top" width="246"&gt;&lt;p&gt;&lt;span class="bold italic "&gt;Näringsdepartementet&lt;/span&gt;&lt;/p&gt;

